export interface PublicKey {
  m: bigint
  e: bigint
}

// Modular exponentiation for BigInt: (base ** exp) % mod
export function modPow(base: bigint, exp: bigint, mod: bigint): bigint {
  let res = 1n
  base = base % mod
  while (exp > 0n) {
    if (exp % 2n === 1n) {
      res = (res * base) % mod
    }
    exp = exp / 2n
    base = (base * base) % mod
  }
  return res
}

export const SERVER_PUBLIC_KEYS = new Map<bigint, PublicKey>([
  [
    -4344800451088585951n,
    {
      m: BigInt(''),
      e: 65537n,
    },
  ],
  [
    847625836280919973n,
    {
      m: BigInt(''),
      e: 65537n,
    },
  ],
  [
    1562291298945373506n,
    {
      m: BigInt(''),
      e: 65537n,
    },
  ],
  [
    -5859577972006586033n,
    {
      m: BigInt(''),
      e: 65537n,
    },
  ],
])

export function rsaEncrypt(data: Buffer, fingerprint: bigint): Buffer {
  const key = SERVER_PUBLIC_KEYS.get(fingerprint)
  if (!key) {
    throw new Error(`RSA public key not found for fingerprint: ${fingerprint}`)
  }

  const dataBigInt = BigInt('0x' + data.toString('hex'))
  const encryptedBigInt = modPow(dataBigInt, key.e, key.m)

  let hex = encryptedBigInt.toString(16)
  if (hex.length % 2 !== 0) hex = '0' + hex
  const buf = Buffer.from(hex, 'hex')

  // Pad to 256 bytes
  if (buf.length < 256) {
    const padded = Buffer.alloc(256)
    buf.copy(padded, 256 - buf.length)
    return padded
  }

  return buf
}
